var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<AccountService>();
var app = builder.Build();

app.MapPost("/withdraw", (WithdrawRequest req, AccountService svc) =>
{
    try
    {
        long balance = svc.Withdraw(req.account, req.amount);
        return Results.Ok(new { balance });
    }
    catch (Exception e)
    {
        // BUG: every service exception becomes 500 - a missing account and an
        // overdraft both look like server errors to the client.
        return Results.Json(new { error = e.Message }, statusCode: 500);
    }
});

app.Run();

