namespace Banking;

public class AccountNotFoundException : Exception
{
    public AccountNotFoundException(string account) : base($"no such account: {account}") { }
}

public class InsufficientFundsException : Exception
{
    public InsufficientFundsException() : base("insufficient funds") { }
}

public class AccountService
{
    private readonly Dictionary<string, long> _balances = new() { ["alice"] = 100 };

    public long Withdraw(string account, long amount)
    {
        if (!_balances.TryGetValue(account, out long balance))
        {
            throw new AccountNotFoundException(account);
        }
        if (amount > balance)
        {
            throw new InsufficientFundsException();
        }
        _balances[account] = balance - amount;
        return _balances[account];
    }
}

