using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class WithdrawTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    public WithdrawTests(WebApplicationFactory<Program> factory) => _factory = factory;

    [Fact]
    public async Task ValidWithdrawalIs200()
    {
        var client = _factory.CreateClient();
        var res = await client.PostAsJsonAsync("/withdraw", new { account = "alice", amount = 40 });
        Assert.Equal(HttpStatusCode.OK, res.StatusCode);
    }

    [Fact]
    public async Task MissingAccountIs404()
    {
        var client = _factory.CreateClient();
        var res = await client.PostAsJsonAsync("/withdraw", new { account = "ghost", amount = 10 });
        Assert.Equal(HttpStatusCode.NotFound, res.StatusCode);
    }

    [Fact]
    public async Task OverdraftIs409()
    {
        var client = _factory.CreateClient();
        var res = await client.PostAsJsonAsync("/withdraw", new { account = "alice", amount = 100000 });
        Assert.Equal(HttpStatusCode.Conflict, res.StatusCode);
    }
}

